<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?php include('includes/page-title.php'); ?><link href="<?= base_url(); ?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/icons.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/app.min.css" rel="stylesheet"><style>body{background:#f4f6fb}.rr-hero{margin:20px 0 24px;padding:28px 30px;border-radius:20px;color:#fff;background:linear-gradient(135deg,#185a9d,#43cea2)}.rr-hero h2{color:#fff;margin:6px 0}.rr-card{border:0;border-radius:14px;box-shadow:0 5px 18px rgba(31,41,55,.09)}.rating{font-weight:700;font-size:1rem}</style></head><body><div id="wrapper"><?php include('includes/top-bar.php'); ?><?php include('includes/sidebar.php'); ?><div class="content-page"><div class="content"><div class="container-fluid"><div class="rr-hero d-flex justify-content-between align-items-center flex-wrap"><div><small class="font-weight-bold text-uppercase">Quality Management System</small><h2>Risk Registry Template</h2><span><?= $esc($sectionName); ?></span></div><div class="mt-3 mt-md-0"><a class="btn btn-light mr-2" href="<?= base_url(); ?>Page/risk_registry_report" target="_blank"><i class="mdi mdi-printer"></i> Generate Report</a><a class="btn btn-outline-light" href="<?= base_url(); ?>Page/risk_registry_add"><i class="mdi mdi-plus"></i> Add Risk</a></div></div><?php if($this->session->flashdata('success')):?><div class="alert alert-success"><?= $esc($this->session->flashdata('success')); ?></div><?php endif;?><?php if($this->session->flashdata('danger')):?><div class="alert alert-danger"><?= $esc($this->session->flashdata('danger')); ?></div><?php endif;?><div class="card rr-card"><div class="card-body"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>#</th><th>Declared Process &amp; Risk</th><th>Current Rating</th><th>Action / Response</th><th>Responsible</th><th>Tar